<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowRight, ArrowUpRight, BookOpen, CalendarDays, Check, CheckCheck, ChevronRight, CircleAlert, CircleCheck, ClipboardCheck, Clock3, FileCheck2, FileText, FolderOpen, LoaderCircle, MessageSquareText, Paperclip, ScanLine, ShieldCheck, Upload, X } from 'lucide-vue-next'
import { inspectionMaterials } from '../mock/data'
import { usePlatformStore } from '../stores/platform'

const store = usePlatformStore()
const route = useRoute()
const selectedIssueId = ref(String(route.query.id || 'XC-WT-001'))
const selectedIssue = computed(() => store.issues.find(i => i.id === selectedIssueId.value) || store.issues[0])
const selectedMaterial = computed(() => inspectionMaterials.find(m => m.id === selectedIssue.value?.materialId) || inspectionMaterials[0])
const selectedTab = ref('问题依据')
const reading = ref(false)
const readingIndex = ref(-1)
const taskModal = ref(false)
const assignee = ref('青禾镇整改工作组')
const deadline = ref('2026-11-12')
const feedback = ref('')
const reviewing = ref(false)
const fileInput = ref<HTMLInputElement | null>(null)
const reviewedCount = computed(() => store.issues.filter(i => i.status !== '待阅卷').length)
const closedCount = computed(() => store.issues.filter(i => i.status === '已销号').length)
const overdueCount = computed(() => store.issues.filter(i => i.deadline && i.deadline < '2026-11-02' && i.status !== '已销号').length)
const currentStage = computed(() => {
  const status = selectedIssue.value?.status
  return status === '待阅卷' ? 1 : status === '待整改' ? 2 : status === '整改中' ? 3 : 4
})
const coverage = computed(() => {
  const text = selectedIssue.value?.response || ''
  if (text.length < 35) return false
  if (/(?:尚未|未能|暂未|未予|无法|未)(?:完成|补充|提供|提交|核对|说明)|(?:材料|附件|佐证)(?:缺失|未提供)|待补充/.test(text)) return false
  const tokens = selectedIssue.value?.id === 'XC-WT-001' ? ['参会', '表决', '签字'] : selectedIssue.value?.id === 'XC-WT-002' ? ['审批', '支付', '凭证'] : ['公开', '登记', '反馈']
  return tokens.filter(token => text.includes(token)).length >= 2
})
const canReview = computed(() => coverage.value && selectedIssue.value?.evidenceAdded)
const relevantEvents = computed(() => store.events.filter(e => /巡察|阅卷|整改|销号|复核/.test(e.action)).slice(0, 3))
const issueClass = (status: string) => status === '已销号' ? 'green' : status === '待复核' ? 'teal' : status === '整改中' ? 'blue' : status === '待整改' ? 'orange' : 'neutral'

function selectMaterial(id: string) {
  const issue = store.issues.find(i => i.materialId === id)
  if (issue) selectedIssueId.value = issue.id
  selectedTab.value = '问题依据'
  feedback.value = ''
}
function selectIssue(id: string) {
  selectedIssueId.value = id
  selectedTab.value = '问题依据'
  feedback.value = ''
}
async function batchReview() {
  if (reading.value) return
  reading.value = true
  for (let index = 0; index < store.issues.length; index++) {
    readingIndex.value = index
    await new Promise(resolve => setTimeout(resolve, 560))
    if (store.issues[index].status === '待阅卷') store.issues[index].status = '待整改'
  }
  readingIndex.value = store.issues.length
  reading.value = false
  store.addEvent('巡察批量辅助阅卷', `完成 ${store.issues.length} 份演示材料检查；纸面疑点已进入人工确认队列`)
  feedback.value = '辅助阅卷完成。以下仅为纸面疑点，请核对原始材料后人工形成整改任务。'
}
function openTaskModal() {
  assignee.value = selectedIssue.value?.area.split(' · ')[0] + '整改工作组'
  taskModal.value = true
}
function createTask() {
  const issue = selectedIssue.value
  if (!issue) return
  store.addTask({ source: '巡察整改', sourceId: issue.id, title: issue.title, area: issue.area, priority: '优先核查', assignee: assignee.value, deadline: deadline.value })
  taskModal.value = false
  selectedTab.value = '整改复核'
  feedback.value = '整改任务已生成，责任单位与办理期限已同步至监督待办。'
}
function useSample(complete: boolean) {
  const issue = selectedIssue.value
  if (!issue) return
  const samples: Record<string, string> = {
    'XC-WT-001': '【虚构演示整改说明】已核对原会议记录，补充完整参会名单、表决过程记录与决议签字页，并说明48,000元道路整修预算审批情况。相关附件已编目留存，现提交巡察组人工复核。',
    'XC-WT-002': '【虚构演示整改说明】已补充事前预算审批表、设备维护合同与验收记录。逐笔核对审批时间及实际支付时间，说明10月15日台账登记与10月18日会议记录的对应关系，支付凭证已随附，请人工复核。',
    'XC-WT-003': '【虚构演示整改说明】已补充带日期的公开栏照片、公开情况登记表及群众反馈处理记录。公开内容与收支汇总表逐项核对，公开时段和反馈事项均已说明，相关佐证材料一并提交人工复核。',
  }
  issue.response = complete ? samples[issue.id] || samples['XC-WT-001'] : '【虚构演示整改说明】相关事项已按要求进行整改，后续将继续完善工作。'
  issue.evidenceAdded = complete
  feedback.value = complete ? '完整样例已载入：回应内容与演示佐证已准备，可提交复核。' : '简略样例已载入：回应未充分覆盖原问题，且缺少佐证材料。'
}
async function uploadResponse(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]
  if (!file || !selectedIssue.value) return
  selectedIssue.value.response = await file.text()
  selectedIssue.value.evidenceAdded = false
  feedback.value = `已读取 ${file.name} 的文本内容。请核对原问题，并确认是否补充演示佐证。`
  store.addEvent('上传整改说明', `${selectedIssue.value.id} · 读取本地文本 ${file.name}，未上传到外部服务`)
  ;(event.target as HTMLInputElement).value = ''
}
function submitForReview() {
  const issue = selectedIssue.value
  if (!issue || !issue.response.trim()) return
  issue.status = '待复核'
  store.addEvent('巡察整改提交复核', `${issue.id} · 回应覆盖${coverage.value ? '完整' : '待补充'}，佐证${issue.evidenceAdded ? '已补充' : '待补充'}`)
  feedback.value = canReview.value ? '整改材料已提交，等待工作人员人工复核。' : '材料已进入待复核队列；辅助比对提示仍需补充，暂不可销号。'
}
async function approve() {
  const issue = selectedIssue.value
  if (!issue || !canReview.value) return
  reviewing.value = true
  await new Promise(resolve => setTimeout(resolve, 450))
  const task = store.tasks.find(t => t.source === '巡察整改' && t.sourceId === issue.id)
  if (task) store.completeTask(task.id)
  issue.status = '已销号'
  store.addEvent('人工复核通过并销号', `${issue.id} · ${issue.title}，已核对整改说明及佐证材料`)
  reviewing.value = false
  feedback.value = '人工复核已通过。问题已销号，关联任务与监督总览已同步更新。'
}
function returnForCorrection() {
  if (!selectedIssue.value) return
  selectedIssue.value.status = '整改中'
  store.addEvent('巡察整改退回补充', `${selectedIssue.value.id} · 请补充覆盖原问题的说明与佐证材料`)
  feedback.value = '已退回责任单位补充，整改任务继续办理。'
}
function isHighlighted(line: string) {
  const issue = selectedIssue.value
  if (!issue || issue.status === '待阅卷') return false
  return line.length > 8 && (line.includes(issue.excerpt) || issue.excerpt.includes(line) || (issue.id === 'XC-WT-002' && (line.includes('10月15日') || line.includes('10月18日'))))
}
watch(() => route.query.id, value => {
  if (value && store.issues.some(issue => issue.id === String(value))) selectIssue(String(value))
})
</script>

<template>
  <div class="inspection-page">
    <div class="page-heading"><div><div class="eyebrow">巡察材料 · 整改闭环</div><h1>巡察与整改</h1><p class="muted">以材料为依据，把发现问题、整改落实与人工复核连成闭环。</p></div><button class="btn btn-primary batch-button" :disabled="reading" @click="batchReview"><LoaderCircle v-if="reading" class="spin" :size="16"/><ScanLine v-else :size="16"/>{{ reading ? `正在阅卷 ${readingIndex + 1} / ${store.issues.length}` : reviewedCount ? '重新辅助阅卷' : '批量辅助阅卷' }}</button></div>

    <div class="inspection-flow panel"><div v-for="(step, index) in [{label:'巡察材料',sub:'原始依据归集',icon:FolderOpen},{label:'辅助阅卷',sub:'识别纸面疑点',icon:ScanLine},{label:'问题归类',sub:'人工确认事项',icon:BookOpen},{label:'整改任务',sub:'跟踪办理进度',icon:ClipboardCheck},{label:'复核销号',sub:'人工审查确认',icon:ShieldCheck}]" :key="step.label" class="flow-step" :class="{ passed: currentStage > index, current: currentStage === index, closed: selectedIssue?.status === '已销号' }"><span class="flow-icon"><Check v-if="currentStage > index || selectedIssue?.status === '已销号'" :size="18"/><component v-else :is="step.icon" :size="19"/></span><div><strong>{{ step.label }}</strong><small>{{ step.sub }}</small></div><ChevronRight v-if="index < 4" class="flow-arrow" :size="16"/></div></div>

    <div class="inspection-summary"><div><span class="summary-dot"></span><strong>{{ reviewedCount }}</strong><span>/ {{ store.issues.length }} 份材料已辅助阅卷</span><i></i><strong>{{ closedCount }}</strong><span>项问题已销号</span></div><div class="summary-progress"><span>闭环完成度</span><div><span :style="{ width: `${closedCount / store.issues.length * 100}%` }"></span></div><b>{{ Math.round(closedCount / store.issues.length * 100) }}%</b></div><span v-if="overdueCount" class="overdue-alert"><Clock3 :size="13"/>{{ overdueCount }} 项逾期</span><span v-else class="no-overdue"><CalendarDays :size="13"/>暂无逾期事项</span></div>

    <div class="inspection-workspace" v-if="selectedMaterial && selectedIssue">
      <aside class="material-library panel"><div class="library-heading"><h3>巡察材料库</h3><span>03</span></div><div class="library-note">虚构样例 · 仅本地演示</div><button v-for="(material, index) in inspectionMaterials" :key="material.id" class="material-choice" :class="{ selected: material.id === selectedMaterial.id, scanning: reading && readingIndex === index }" @click="selectMaterial(material.id)"><span class="material-icon"><FileText :size="19"/></span><span class="material-meta">{{ material.type }}<small>{{ material.date }}</small></span><strong>{{ material.title }}</strong><span class="material-foot"><span :class="['status-dot', store.issues.find(i => i.materialId === material.id)?.status === '待阅卷' ? 'gray' : 'teal-dot']"></span>{{ store.issues.find(i => i.materialId === material.id)?.status === '待阅卷' ? '待辅助阅卷' : '已完成辅助阅卷' }}<Check v-if="store.issues.find(i => i.materialId === material.id)?.status !== '待阅卷'" :size="12"/></span></button><div class="library-footer"><ShieldCheck :size="16"/><span>AI 只提示纸面疑点<br/>不替代业务事实核实</span></div></aside>

      <section class="material-reader panel"><div class="reader-toolbar"><div><FileText :size="16"/><span>原始材料</span></div><span class="reader-format">文本样例</span><span class="reader-counter">{{ inspectionMaterials.findIndex(m => m.id === selectedMaterial.id) + 1 }} / 3</span></div><div class="material-paper"><div class="paper-demo">虚构演示材料</div><h2>{{ selectedMaterial.title }}</h2><div class="paper-meta"><span>{{ selectedMaterial.area }}</span><span>{{ selectedMaterial.date }}</span></div><div class="paper-divider"></div><div class="paper-content"><template v-for="(line, index) in selectedMaterial.content.split('\n').slice(2)" :key="index"><p v-if="line.trim()" :class="{ highlighted: isHighlighted(line) }">{{ line }}</p><div v-else class="paragraph-space"></div></template></div><div class="paper-end">— 原始样例材料结束 —</div></div><div class="reader-foot"><span><span class="highlight-key"></span>{{ selectedIssue.status === '待阅卷' ? '完成辅助阅卷后定位相关段落' : '浅色标注为辅助检查关注段落' }}</span><span>来源编号 {{ selectedMaterial.id }}</span></div></section>

      <aside class="issue-workbench panel"><div class="workbench-tabs"><button :class="{active:selectedTab === '问题依据'}" @click="selectedTab = '问题依据'"><ScanLine :size="15"/>问题依据<span>{{ store.issues.length }}</span></button><button :class="{active:selectedTab === '整改复核'}" @click="selectedTab = '整改复核'"><ClipboardCheck :size="15"/>整改复核<span v-if="selectedIssue.status === '待复核'" class="review-dot"></span></button></div>

        <template v-if="selectedTab === '问题依据'"><div class="issue-list"><button v-for="issue in store.issues" :key="issue.id" class="issue-choice" :class="{selected: selectedIssueId === issue.id}" @click="selectIssue(issue.id)"><span class="issue-index">{{ issue.id.slice(-2) }}</span><span><strong>{{ issue.title }}</strong><small>{{ issue.area }}</small></span><span class="badge" :class="issueClass(issue.status)">{{ issue.status }}</span></button></div><div v-if="selectedIssue.status === '待阅卷'" class="before-reading"><span class="scan-orb"><ScanLine :size="30" stroke-width="1.3"/></span><h3>从原始材料中发现关注点</h3><p>对会议记录要素、支出审批时序与公开佐证进行模拟检查，结果由工作人员确认。</p><button class="btn btn-primary" :disabled="reading" @click="batchReview"><ScanLine :size="15"/>{{ reading ? '正在辅助阅卷…' : '开始辅助阅卷' }}</button><span>本地规则模拟 · 未接入大模型</span></div><div v-else class="issue-evidence"><div class="issue-evidence-heading"><span class="evidence-kicker">阅卷检查依据</span><span class="auxiliary-label">辅助疑点</span></div><h3>{{ selectedIssue.title }}</h3><blockquote><span>原材料摘录</span>{{ selectedIssue.excerpt }}</blockquote><div class="check-line"><ScanLine :size="15"/><div><span>检查事项</span><p>{{ selectedIssue.check }}</p></div></div><div class="check-line"><Paperclip :size="15"/><div><span>建议补充材料</span><p>{{ selectedIssue.suggestion }}</p></div></div><div class="issue-disclaimer"><CircleAlert :size="15"/><span>材料缺失不等于实际程序缺失，请调阅完整资料后人工确认。</span></div><button v-if="selectedIssue.status === '待整改'" class="btn btn-primary generate-task" @click="openTaskModal"><ClipboardCheck :size="16"/>人工确认，生成整改任务</button><button v-else class="btn btn-quiet generate-task" @click="selectedTab = '整改复核'">{{ selectedIssue.status === '已销号' ? '查看复核与销号记录' : '进入整改办理' }}<ArrowRight :size="15"/></button></div></template>

        <template v-else><div class="rectification-content"><div class="rectification-title"><span class="evidence-kicker">整改办理与人工复核</span><span class="badge" :class="issueClass(selectedIssue.status)">{{ selectedIssue.status }}</span></div><h3>{{ selectedIssue.title }}</h3><template v-if="['待阅卷','待整改'].includes(selectedIssue.status)"><div class="rectification-empty"><ClipboardCheck :size="34" stroke-width="1.3"/><h4>先确认问题，再形成任务</h4><p>人工确认辅助疑点后，指定责任单位与办理时限，开始整改跟踪。</p><button class="btn btn-primary" @click="selectedIssue.status === '待阅卷' ? batchReview() : openTaskModal()">{{ selectedIssue.status === '待阅卷' ? '先完成辅助阅卷' : '生成整改任务' }}</button></div></template><template v-else><div class="task-info"><span><FolderOpen :size="14"/>{{ selectedIssue.assignee || '整改责任单位' }}</span><span><CalendarDays :size="14"/>{{ selectedIssue.deadline || '2026-11-12' }} 前完成</span></div><div v-if="selectedIssue.status === '已销号'" class="closed-banner"><CircleCheck :size="25"/><div><strong>人工复核通过，已完成销号</strong><span>整改说明与演示佐证已核对，关联任务已完成。</span></div></div><div class="response-heading"><h4>整改说明</h4><span v-if="selectedIssue.status === '已销号'">已归档</span><button v-else class="text-button" @click="fileInput?.click()"><Upload :size="13"/>上传 .txt</button><input ref="fileInput" type="file" accept=".txt" style="display:none" @change="uploadResponse"/></div><textarea v-model="selectedIssue.response" :readonly="selectedIssue.status === '已销号'" placeholder="填写整改回应，说明如何覆盖原问题，并列明相应佐证材料…" class="response-input"></textarea><div v-if="selectedIssue.status !== '已销号'" class="sample-actions"><span>演示样例</span><button @click="useSample(false)">简略说明</button><button @click="useSample(true)">完整说明 + 佐证<ArrowUpRight :size="11"/></button></div><label class="evidence-checkbox" :class="{checked:selectedIssue.evidenceAdded}"><input type="checkbox" v-model="selectedIssue.evidenceAdded" :disabled="selectedIssue.status === '已销号'"/><Paperclip :size="14"/><span>已补充演示佐证材料</span><Check v-if="selectedIssue.evidenceAdded" :size="13"/></label><div class="coverage-analysis" v-if="selectedIssue.response"><div class="coverage-heading"><ScanLine :size="14"/><strong>回应覆盖辅助比对</strong><span>演示规则</span></div><div><span>原问题回应</span><strong :class="coverage ? 'positive' : 'needs-work'"><Check v-if="coverage" :size="12"/><CircleAlert v-else :size="12"/>{{ coverage ? '已覆盖关键事项' : '内容待补充' }}</strong></div><div><span>佐证材料</span><strong :class="selectedIssue.evidenceAdded ? 'positive' : 'needs-work'"><Check v-if="selectedIssue.evidenceAdded" :size="12"/><CircleAlert v-else :size="12"/>{{ selectedIssue.evidenceAdded ? '已补充演示附件' : '缺少核实佐证' }}</strong></div></div><div v-if="selectedIssue.status === '整改中'" class="rectification-actions"><button class="btn btn-primary" :disabled="!selectedIssue.response.trim()" @click="submitForReview"><FileCheck2 :size="15"/>提交整改复核</button></div><div v-else-if="selectedIssue.status === '待复核'" class="review-actions"><div class="human-review-tip"><ShieldCheck :size="14"/>请人工审阅说明及佐证后确认</div><div><button class="btn btn-quiet" @click="returnForCorrection">退回补充</button><button class="btn btn-primary" :disabled="!canReview || reviewing" @click="approve"><LoaderCircle v-if="reviewing" :size="14" class="spin"/><CheckCheck v-else :size="15"/>人工复核通过</button></div><span v-if="!canReview" class="review-block">原问题回应与佐证完整后，才能人工复核销号。</span></div></template></div></template>
        <div v-if="feedback" class="inspection-feedback"><CircleCheck :size="15"/><span>{{ feedback }}</span></div><div class="workbench-bottom"><ShieldCheck :size="13"/>AI 辅助结果，需人工复核</div>
      </aside>
    </div>

    <div class="operation-trail"><div><Clock3 :size="14"/><strong>操作留痕</strong></div><span v-for="event in relevantEvents.slice(0, 2)" :key="event.id"><b>{{ event.time.slice(-5) }}</b>{{ event.action }}</span><span v-if="!relevantEvents.length">完成辅助阅卷后，操作记录将在此呈现</span></div>

    <Teleport to="body"><div v-if="taskModal && selectedIssue" class="inspection-modal-backdrop" @click.self="taskModal = false"><form class="inspection-task-modal" @submit.prevent="createTask"><header><span class="modal-task-icon"><ClipboardCheck :size="23"/></span><button type="button" aria-label="关闭" class="icon-close" @click="taskModal = false"><X :size="19"/></button></header><div class="eyebrow">人工确认</div><h2>生成整改任务</h2><p>请确认问题依据，并明确责任单位和办理期限。</p><div class="modal-issue"><span>{{ selectedIssue.id }}</span><strong>{{ selectedIssue.title }}</strong><small>{{ selectedIssue.area }}</small></div><label>责任单位<select class="field" v-model="assignee"><option>{{ selectedIssue.area.split(' · ')[0] }}整改工作组</option><option>县级巡察整改专班</option><option>村级整改责任组</option></select></label><label>办理期限<input v-model="deadline" class="field" type="date" required/></label><div class="modal-boundary"><ShieldCheck :size="14"/>人工确认后生成任务，AI 不自动下发整改决定。</div><footer><button class="btn btn-quiet" type="button" @click="taskModal = false">取消</button><button class="btn btn-primary" type="submit"><Check :size="15"/>确认生成任务</button></footer></form></div></Teleport>
  </div>
</template>

